client_script:
// 1. INITIALIZATION LOGIC (Runs automatically when the form loads)
frappe.web_form.after_load = () => {
    // A. Read parameters from URL query strings
    let flight = frappe.utils.get_url_arg("airplane-flight");
    let price = frappe.utils.get_url_arg("flight-price");

    if (flight) {
        frappe.web_form.set_value("flight", flight);
    }

    if (price) {
        frappe.web_form.set_value("flight_price", price);
        frappe.web_form.set_value("total_amount", price); // Set initial base amount total
    }

    // Keep the base price securely locked as read-only
    frappe.web_form.set_df_property("flight_price", "read_only", 1);

    // B. CHILD TABLE INTERCEPT (Forces add-on rows to render as selectable dropdowns)
    frappe.web_form.on('add_ons', (type, field, row) => {
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Airplane Ticket Add-on Item", // Ensure spelling matches your master Doctype!
                fields: ["name", "amount"]
            },
            callback: function(r) {
                if (r.message) {
                    // Turn item listings into distinct selectable option structures
                    let options = r.message.map(item => {
                        return { value: item.name, label: `${item.name} (TZS ${item.amount})` };
                    });

                    // Convert table inputs into Select menus dynamically
                    let grid = frappe.web_form.fields_dict['add_ons'].grid;

                    // Applies dropdown properties to whichever column field holds your item link name
                    if(grid.df.fields.find(f => f.fieldname === 'item')) {
                        grid.set_field_property('item', 'fieldtype', 'Select');
                        grid.set_field_property('item', 'options', options);
                    } else if(grid.df.fields.find(f => f.fieldname === 'item_name')) {
                        grid.set_field_property('item_name', 'fieldtype', 'Select');
                        grid.set_field_property('item_name', 'options', options);
                    }

                    grid.refresh();
                }
            }
        });
    });
};

// 2. REDIRECT INTERCEPT (Runs instantly when they click "Confirm" successfully)
frappe.web_form.handle_success = function (data) {
    window.location.href = "/ticket-review?ticket=" + encodeURIComponent(data.name);
};
// 3. MATHEMATICAL PRICING AUTOMATION (Recalculates totals when rows are altered)
frappe.web_form.on('add_ons', 'item', (doctype, fieldname, row_id) => {
    recalculate_total_booking_price();
});

frappe.web_form.on('add_ons', 'item_name', (doctype, fieldname, row_id) => {
    recalculate_total_booking_price();
});

function recalculate_total_booking_price() {
    let grid = frappe.web_form.fields_dict['add_ons'].grid;
    let base_price = parseFloat(frappe.web_form.get_value("flight_price") || 0);
    let addons_total = 0;

    grid.get_data().forEach(d => {
        addons_total += parseFloat(d.amount || 0);
    });

    // Write updated calculation figures directly into your form field row
    frappe.web_form.set_value("total_amount", base_price + addons_total);
}

custom_css:
/* Container Layout Makeover */
.web-form-container {
    max-width: 850px !important;
    margin: 40px auto !important;
    background: #ffffff;
    border-radius: 24px !important;
    box-shadow: 0 20px 50px rgba(30, 60, 114, 0.12) !important;
    overflow: hidden;
    border: 1px solid rgba(0,0,0,0.02);
}

/* Beautiful Modern Header Modification */
.web-form-header {
    background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%) !important;
    padding: 40px 30px !important;
    text-align: center;
    border-bottom: 0px !important;
}
.web-form-header h1, .web-form-header h2 {
    color: #ffffff !important;
    font-weight: 800 !important;
    letter-spacing: 0.5px;
    font-size: 28px !important;
    text-transform: uppercase;
}
.web-form-header .introduction_text {
    color: rgba(255,255,255,0.7) !important;
    font-size: 14px;
    margin-top: 5px;
}

/* Input Form Input Field Refinements */
.web-form-page {
    padding: 40px 50px !important;
}
.form-group {
    margin-bottom: 25px !important;
}
.control-label {
    font-weight: 700 !important;
    color: #34495e !important;
    font-size: 13px !important;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px !important;
}
input[type="text"], input[type="email"], select, .form-control {
    height: 52px !important;
    border-radius: 12px !important;
    border: 2px solid #e2e8f0 !important;
    background-color: #f8fafc !important;
    padding: 10px 16px !important;
    font-size: 15px !important;
    color: #1a202c !important;
    transition: all 0.25s ease-in-out !important;
}
input[type="text"]:focus, select:focus, .form-control:focus {
    border-color: #3182ce !important;
    background-color: #ffffff !important;
    box-shadow: 0 0 0 4px rgba(49, 130, 206, 0.1) !important;
}

/* Price Box Highlight */
[data-fieldname="flight_price"] input {
    background: #ebf8ff !important;
    border-color: #bee3f8 !important;
    color: #2b6cb0 !important;
    font-weight: 800 !important;
    font-size: 18px !important;
}

/* Redesigned Button Actions */
.web-form-actions {
    padding: 20px 50px 40px !important;
    background: #ffffff !important;
    border-top: 0px !important;
}
.btn-primary.btn-form-submit {
    background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%) !important;
    border: none !important;
    height: 54px !important;
    border-radius: 12px !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    letter-spacing: 0.5px;
    box-shadow: 0 10px 20px rgba(56, 239, 125, 0.25) !important;
    transition: all 0.2s !important;
}
.btn-primary.btn-form-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 24px rgba(56, 239, 125, 0.35) !important;
}
.btn-default {
    height: 54px !important;
    border-radius: 12px !important;
    border: 2px solid #e2e8f0 !important;
    font-weight: 600 !important;
}
